import {
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  booleanAttribute,
  input,
  inject,
} from '@angular/core';

@Component({
  selector: 'textarea[aevkoTextarea]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './textarea.directive.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'textarea',
    '[attr.aria-invalid]': 'invalid() ? "true" : null',
    '[attr.data-invalid]': 'invalid() ? "true" : null',
    '[attr.data-auto-resize]': 'autoResize() ? "true" : null',
    '(input)': 'resize()',
  },
})
export class AevkoTextarea implements AfterViewInit {
  private readonly element = inject<ElementRef<HTMLTextAreaElement>>(ElementRef);
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly autoResize = input(false, { transform: booleanAttribute });

  ngAfterViewInit(): void {
    this.resize();
  }

  protected resize(): void {
    if (!this.autoResize()) {
      return;
    }
    const textarea = this.element.nativeElement;
    textarea.style.height = 'auto';
    textarea.style.height = `${textarea.scrollHeight}px`;
  }
}

:host {
  background: var(--aevko-background, #ffffff);
  border: 1px solid color-mix(in srgb, var(--aevko-foreground, #20201e) 45%, transparent);
  border-radius: var(--aevko-radius, 0);
  box-sizing: border-box;
  color: var(--aevko-foreground, #20201e);
  font: 500 1rem/1.5 var(--aevko-font-sans, sans-serif);
  min-height: 7rem;
  padding: 0.625rem 0.75rem;
  resize: vertical;
  width: 100%;
}
:host:focus-visible {
  border-color: var(--aevko-focus, #a1a1aa);
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
:host:hover:not(:disabled) {
  border-color: var(--aevko-foreground, #20201e);
}
:host([data-invalid='true']) {
  border-color: var(--aevko-danger, #3f3f3f);
}
:host([data-invalid='true']):focus-visible {
  outline-color: color-mix(in srgb, var(--aevko-danger, #3f3f3f) 55%, transparent);
}
:host([data-auto-resize='true']) {
  overflow: hidden;
  resize: none;
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
